// WebWatchFindingsSchema returns the schema of agent_web_watch_findings.
func WebWatchFindingsSchema() *schema.Table { return &webWatchFindingsTable }

// As returns a handle that references agent_web_watch_findings under its own alias.
func (t *WebWatchFindingsTable) As(alias string) *WebWatchFindingsTable {
	return keel.Alias(t.Ref, alias, BuildWebWatchFindings)
}

// Get returns the agent_web_watch_findings row with the given key, or keel.ErrNotFound.
func (t *WebWatchFindingsTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*extensionwebwatch.WebWatchFinding, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newWebWatchFinding() unsafe.Pointer { return unsafe.Pointer(new(extensionwebwatch.WebWatchFinding)) }

func newNWebWatchFinding(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]extensionwebwatch.WebWatchFinding, n)))
}

func ptrWebWatchFinding(p unsafe.Pointer, c int32) any {
	r := (*extensionwebwatch.WebWatchFinding)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WatchID))
	case 4:
		return &r.VendorRunID
	case 5:
		return &r.Summary
	case 6:
		return &r.Results
	case 7:
		return &r.FoundAt
	case 8:
		return &r.DeliveredAt
	case 9:
		return &r.CreatedAt
	}
	return nil
}

func valueWebWatchFinding(p unsafe.Pointer, c int32) any {
	r := (*extensionwebwatch.WebWatchFinding)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WatchID)
	case 4:
		return r.VendorRunID
	case 5:
		return r.Summary
	case 6:
		if r.Results == nil {
			return keel.EmptyJSONArray
		}
		return r.Results
	case 7:
		return r.FoundAt
	case 8:
		if r.DeliveredAt == nil {
			return nil
		}
		return *r.DeliveredAt
	case 9:
		return r.CreatedAt
	}
	return nil
}

